B.bT7=new A.jE("Hot left, cold right","On a faucet, hot is on the left and cold on the right. Hot lines are marked red and cold lines blue.")
B.bTk=new A.jE("The P-trap","The curved pipe under a sink always holds a little water. That water seal stops sewer gas coming up the drain.")
B.bTv=new A.jE("Shut-off valves","Every sink and toilet has its own small valve, so you can stop the water to one fixture without turning off the whole house.")
B.bTd=new A.jE("Slip nuts","Drain joints are sealed by a washer and a slip nut. Tighten by hand and a quarter turn: too much force cracks plastic.")
B.bTc=new A.jE("Wax ring","A toilet sits on a wax ring that seals it to the floor drain. A toilet is lowered straight down once, and cannot be slid around.")
B.bTs=new A.jE("Drain slope","Drains fall about 1/4 inch per foot so water and waste keep moving. Too flat and it clogs, too steep and the water leaves the solids behind.")
B.bTx=new A.jE("Order of work","Plumbing goes from the top down on the drain (tailpiece, trap, arm) and from the wall out on the supply (valve, hose, fixture).")
B.cag=w([B.bT7,B.bTk,B.bTv,B.bTd,B.bTc,B.bTs,B.bTx],x.Z)
B.bTD=new A.Mr("Plumbing basics","\ud83d\udeb0",D.co,B.cag)
B.bT9=new A.jE("Studs","Studs are the vertical 2x4 posts inside a wall, 16 inches apart from centre to centre. Everything is fixed to them.")
B.bTn=new A.jE("Drilling studs","Holes for cable go through the middle of the stud, so a nail or screw cannot reach the wire.")
B.bTe=new A.jE("Drywall","A sheet is 4 feet wide, so its edges land on studs 48 inches apart. Screws go into studs only, just under the paper.")
B.bTh=new A.jE("Taping and mud","Seams get paper tape and three thin coats of joint compound, sanded smooth between coats, then primer and paint.")
B.bTw=new A.jE("Order of a build","Frame, run the pipes and wires (rough-in), inspect, hang drywall, finish it, paint, then fit the fixtures and devices.")
B.cOt=w([B.bT9,B.bTn,B.bTe,B.bTh,B.bTw],x.Z)
B.bTB=new A.Mr("Framing and walls","\ud83c\udfe0",D.dT,B.cOt)
B.bTi=new A.jE("Voltage tester","A pen that glows or beeps near live wires. Test it on a known live outlet first, so you know it works.")
B.bTo=new A.jE("Wire strippers","Strip the plastic off without nicking the copper. A nick weakens the wire.")
B.bTu=new A.jE("Adjustable wrench","For nuts on valves and hoses. Hold the fitting steady with a second wrench so you do not twist the pipe.")
B.bTm=new A.jE("Drill and screw gun","A drill makes holes through studs. A screw gun sets drywall screws to the right depth.")
B.bTg=new A.jE("Level and tape measure","Measure twice, cut once. A level makes sure outlets, shelves and pipes are straight.")
